begin;
select no_plan();
create function pg_temp.tid(n integer) returns uuid language sql as $$select ('ef760000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.tid(1),'translation-owner@example.test');
insert into public.goals(id,owner_id,blueprint_id,title,position) select pg_temp.tid(10),owner_id,id,'Goal',0 from public.blueprints where owner_id=pg_temp.tid(1);
insert into public.stages(id,owner_id,goal_id,title,position) values(pg_temp.tid(11),pg_temp.tid(1),pg_temp.tid(10),'Stage',0);
insert into public.path_nodes(id,owner_id,stage_id,node_type,title,position) values(pg_temp.tid(12),pg_temp.tid(1),pg_temp.tid(11),'practice','Practice',0);
insert into public.resource_bindings(id,owner_id,node_id,kind,url,external_id,position)
 values(pg_temp.tid(13),pg_temp.tid(1),pg_temp.tid(12),'youtube_video','https://www.youtube.com/watch?v=abcdefghijk','abcdefghijk',0);
insert into private.resource_retention_policies values(pg_temp.tid(1),86400,'local-translation-fixture');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated')::text,true);
insert into public.resource_runs(id,owner_id,blueprint_id,blueprint_version,node_id,kind,preferences,learner_context,input_blueprint,result,status,expires_at)
 select pg_temp.tid(20),owner_id,id,version,pg_temp.tid(12),'discover','{}','{}',public.read_blueprint_snapshot_v2(owner_id),
 '{"status":"discovered","candidates":[{"video":{"videoId":"abcdefghijk","title":"Saved video"},"transcript":{"status":"ready","language":"en","segments":[{"text":"  Do not double ISO.  ","offset":1250,"duration":2000},{"text":"Try again.","offset":3250,"duration":1500}]}}]}',
 'ready',clock_timestamp()+interval '120 seconds' from public.blueprints where owner_id=pg_temp.tid(1);
create function pg_temp.req(n integer) returns jsonb language sql as $$select jsonb_build_object('runId',pg_temp.tid(n),'bindingId',pg_temp.tid(13),'videoId','abcdefghijk','sourceRunId',pg_temp.tid(20),'offset',0,'targetLanguage','zh-Hans')$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated')::text,true);
select throws_ok($$select public.begin_translation_run(pg_temp.req(30))$$,'P0001','TRANSLATION_QUOTA_EXHAUSTED','translation cannot consume without configured quota');
reset role;
insert into private.translation_run_quotas values(pg_temp.tid(1),5);
set local role authenticated;
select is(public.begin_translation_run(pg_temp.req(30))->>'status','queued','explicit begin queues one durable run');
select is(public.read_translation_run(pg_temp.tid(30))#>>'{input_page,segments,0,text}','  Do not double ISO.  ','frozen caption comes from server source verbatim');
select is(public.begin_translation_run(pg_temp.req(30)),public.read_translation_run(pg_temp.tid(30)),'identical begin is exact receipt recovery');
select throws_ok($$select public.begin_translation_run(pg_temp.req(31))$$,'P0001','TRANSLATION_BUSY','second active run cannot charge quota');
select throws_ok($$select public.begin_translation_run(pg_temp.req(30)||'{"offset":20}')$$,'22023','TRANSLATION_ID_REUSED','same id cannot change pinned page');
reset role;
create function pg_temp.skill() returns jsonb language sql as $$select jsonb_build_object('name','blueprint-translate-transcript','version','1.0.0','instructions','Translate fixture','sha256',encode(extensions.digest('Translate fixture','sha256'),'hex'))$$;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(90),pg_temp.skill(),'deepseek-v4-flash')->>'acquired','true','service claims once before model execution');
select is(public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(91),null,null)->>'acquired','false','another lease never reacquires existing run');
create function pg_temp.result() returns jsonb language sql as $$select '{"status":"translated","segments":[{"segmentIndex":0,"translation":"不要加倍 ISO。"},{"segmentIndex":1,"translation":"再试一次。"}],"providerMayHaveRun":true,"usage":{"inputTokens":20,"outputTokens":30,"totalTokens":50}}'::jsonb$$;
select is(public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(90),pg_temp.result())->>'status','ready','one exact completion becomes durable translated result');
select is(public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(90),pg_temp.result())->>'status','ready','exact finish retry is idempotent');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(91),pg_temp.result())$$,'42501','TRANSLATION_LEASE_INVALID','wrong lease cannot read or replace completion');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(90),jsonb_set(pg_temp.result(),'{segments,0,translation}','"Different"'))$$,'22023','TRANSLATION_COMPLETION_REUSED','different finish cannot overwrite exact receipt');
reset role;
select is((select remaining from private.translation_run_quotas where owner_id=pg_temp.tid(1)),4,'begin retry and claim replay only charge once');
select throws_ok($$update private.translation_runs set content_expires_at=content_expires_at+interval '1 day' where id=pg_temp.tid(30)$$,'22023','TRANSLATION_SOURCE_IMMUTABLE','source deadline cannot be extended');
select throws_ok($$update private.translation_runs set input_page=jsonb_set(input_page,'{segments,0,text}','"changed"') where id=pg_temp.tid(30)$$,'22023','TRANSLATION_SOURCE_IMMUTABLE','original source page is immutable');

set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated')::text,true);
select throws_ok($$select public.begin_translation_run(pg_temp.req(31)||'{"text":"CLIENT_CAPTION"}')$$,'22023','TRANSLATION_INVALID','client cannot provide caption body');
select throws_ok($$select public.begin_translation_run(pg_temp.req(31)||'{"offset":1}')$$,'22023','TRANSLATION_INVALID','non-page boundary invalid');
select throws_ok($$select public.begin_translation_run(pg_temp.req(31)||'{"sourceRunId":null}')$$,'22023','TRANSLATION_INVALID','unpinned source invalid');
select throws_ok($$select public.begin_translation_run(pg_temp.req(31)||'{"targetLanguage":"en"}')$$,'22023','TRANSLATION_INVALID','unapproved target language invalid');
select throws_ok($$select public.begin_translation_run(pg_temp.req(31)||'{"offset":20}')$$,'P0001','TRANSLATION_NO_EVIDENCE','empty source page cannot create a run');
select is(public.begin_translation_run(pg_temp.req(31))->>'status','queued','ready prior run does not block new explicit run');
select is(public.cancel_translation_run(pg_temp.tid(31))#>>'{result,providerMayHaveRun}','false','queued cancellation has no provider uncertainty');
select is(public.cancel_translation_run(pg_temp.tid(31))->>'status','cancelled','repeat cancellation is stable');
select is(public.begin_translation_run(pg_temp.req(31))->>'status','cancelled','old cancelled id cannot execute again');
reset role;
select is((select remaining from private.translation_run_quotas where owner_id=pg_temp.tid(1)),4,'unclaimed cancellation refunds exactly once');
set local role authenticated;
select is(public.begin_translation_run(pg_temp.req(32))->>'status','queued','new operation after cancellation');
reset role;
set local role service_role;
select throws_ok($$select public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),pg_temp.skill()||'{"sha256":"bad"}','deepseek-v4-flash')$$,'22023','TRANSLATION_INVALID','Skill hash cannot be forged');
select throws_ok($$select public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),pg_temp.skill(),'')$$,'22023','TRANSLATION_INVALID','empty model invalid');
select is(public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),pg_temp.skill(),'deepseek-v4-flash')#>>'{run,model}','deepseek-v4-flash','model is pinned on first valid claim');
select ok((public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(93),null,null)->>'observed_at')::timestamptz<=clock_timestamp(),'claim replay has current database observation');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),pg_temp.result()-'segments')$$,'22023','TRANSLATION_INVALID_RESULT','missing segments rejected');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),jsonb_set(pg_temp.result(),'{segments,1,segmentIndex}','0'))$$,'22023','TRANSLATION_INVALID_RESULT','duplicate indexes rejected');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),jsonb_set(pg_temp.result(),'{segments,0,segmentIndex}','1'))$$,'22023','TRANSLATION_INVALID_RESULT','reordered indexes rejected');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),jsonb_set(pg_temp.result(),'{segments,0,translation}','"  "'))$$,'22023','TRANSLATION_INVALID_RESULT','blank translation rejected');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),jsonb_set(pg_temp.result(),'{segments,0,translation}',to_jsonb(repeat('😀',10001))))$$,'22023','TRANSLATION_INVALID_RESULT','astral text obeys UTF16 limit');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),pg_temp.result()||'{"sourceRunId":"spoof"}')$$,'22023','TRANSLATION_INVALID_RESULT','completion cannot choose source metadata');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),jsonb_set(pg_temp.result(),'{usage,inputTokens}','-1'))$$,'22023','TRANSLATION_INVALID_RESULT','negative usage rejected');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),jsonb_set(pg_temp.result(),'{usage,outputTokens}','0.5'))$$,'22023','TRANSLATION_INVALID_RESULT','fractional usage rejected');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),jsonb_set(pg_temp.result(),'{providerMayHaveRun}','false'))$$,'22023','TRANSLATION_INVALID_RESULT','translated receipt cannot deny model execution');
reset role;
set local role authenticated;
select is(public.read_translation_run(pg_temp.tid(32))->>'status','running','invalid completions never alter original run');
select is(public.cancel_translation_run(pg_temp.tid(32))#>>'{result,providerMayHaveRun}','true','claimed cancellation preserves execution uncertainty');
reset role;
set local role service_role;
select is(public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),pg_temp.result())->>'status','cancelled','late valid finish cannot revive cancelled run');
select is(public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(32),pg_temp.tid(92),pg_temp.result())->>'status','cancelled','late completion exact digest remains recoverable');
reset role;
select is((select remaining from private.translation_run_quotas where owner_id=pg_temp.tid(1)),3,'claimed cancellation never refunds');

-- Existing acquisition revision need not equal the current formal Blueprint.
update public.blueprints set version=version+1 where owner_id=pg_temp.tid(1);
update public.resource_runs set status='stale' where id=pg_temp.tid(20);
set local role authenticated;
select is(public.begin_translation_run(pg_temp.req(33))#>>'{input_page,sourceBlueprintVersion}','0','current practice binding accepts historical source revision');
reset role;
update private.translation_runs set expires_at=clock_timestamp()-interval '1 second' where id=pg_temp.tid(33);
set local role authenticated;
select is(public.read_translation_run(pg_temp.tid(33))->>'status','cancelled','queued operation deadline reconciles on read');
select is(public.read_translation_run(pg_temp.tid(33))#>>'{result,providerMayHaveRun}','false','queue expiry records no provider execution');
select public.begin_translation_run(pg_temp.req(34));
reset role;
set local role service_role;
select public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(34),pg_temp.tid(94),pg_temp.skill(),'deepseek-v4-flash');
reset role;
update private.translation_runs set expires_at=clock_timestamp()-interval '1 second' where id=pg_temp.tid(34);
set local role authenticated;
select is(public.read_translation_run(pg_temp.tid(34))->>'status','interrupted','running deadline reconciles without revival');
select is(public.read_translation_run(pg_temp.tid(34))#>>'{result,status}','timed_out','run expiry is a timed out receipt');
reset role;
select is((select remaining from private.translation_run_quotas where owner_id=pg_temp.tid(1)),2,'queue expiry refunds once, running expiry never refunds');

-- Private tables and privileged workers never become a client data API.
insert into auth.users(id,email) values(pg_temp.tid(2),'translation-other@example.test');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(2),'role','authenticated')::text,true);
select throws_ok($$select public.read_translation_run(pg_temp.tid(30))$$,'P0002','TRANSLATION_NOT_FOUND','other owner cannot read existing id');
select throws_ok($$select public.begin_translation_run(pg_temp.req(30))$$,'P0002','TRANSLATION_NOT_FOUND','other owner cannot reuse known id');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated','client_id','any-client')::text,true);
select throws_ok($$select public.read_translation_run(pg_temp.tid(30))$$,'42501','TRANSLATION_FORBIDDEN','all OAuth clients denied translation body');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated','client_id',null)::text,true);
select throws_ok($$select public.read_translation_run(pg_temp.tid(30))$$,'42501','TRANSLATION_FORBIDDEN','present null client id is not a Web token');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated','is_anonymous',true)::text,true);
select throws_ok($$select public.read_translation_run(pg_temp.tid(30))$$,'42501','TRANSLATION_FORBIDDEN','anonymous Auth user denied');
select throws_ok($$select * from private.translation_runs$$,'42501',null,'authenticated direct table read denied');
select throws_ok($$select public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(90),pg_temp.skill(),'model')$$,'42501',null,'authenticated cannot claim');
reset role;
set local role service_role;
select throws_ok($$select * from private.translation_runs$$,'42501',null,'service role cannot select private content table directly');
select throws_ok($$update private.translation_run_quotas set remaining=999$$,'42501',null,'service role cannot self-grant translation quota');
select throws_ok($$select public.read_translation_run(pg_temp.tid(30))$$,'42501',null,'service role cannot use Web read RPC');
reset role;
set local role anon;
select throws_ok($$select public.read_translation_run(pg_temp.tid(30))$$,'42501',null,'anon cannot read');
select throws_ok($$select public.begin_translation_run(pg_temp.req(99))$$,'42501',null,'anon cannot begin');
reset role;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated')::text,true);
select public.begin_translation_run(pg_temp.req(35));
select public.clear_resource_evidence(pg_temp.tid(20));
reset role;
select is((select status from private.translation_runs where id=pg_temp.tid(30)),'cleared','original chain clearing synchronously clears derivative before another read');
select ok((select input_page is null and skill is null and model is null and result is null from private.translation_runs where id=pg_temp.tid(30)),'clearing physically removes all derivative bodies');
select is((select remaining from private.translation_run_quotas where owner_id=pg_temp.tid(1)),2,'manual clear refunds only queued derivative');
set local role authenticated;
select is(public.read_translation_run(pg_temp.tid(30))->>'clear_reason','manual','manual source clearing keeps reason on translated receipt');
select is(public.begin_translation_run(pg_temp.req(30))->>'status','cleared','same cleared id does not regenerate');
select throws_ok($$select public.begin_translation_run(pg_temp.req(36))$$,'P0001','TRANSLATION_NO_EVIDENCE','new generation on cleared source denied');
reset role;
set local role service_role;
select is(public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(90),'null')->>'status','cleared','cleared late finish returns tombstone before payload parsing');
select throws_ok($$select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(30),pg_temp.tid(91),'null')$$,'42501','TRANSLATION_LEASE_INVALID','cleared late finish still validates original lease');
select is(public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(35),pg_temp.tid(95),null,null)->>'acquired','false','cleared queued run cannot be claimed');
reset role;

create function pg_temp.source(n integer) returns void language sql as $$
 insert into public.resource_runs(id,owner_id,blueprint_id,blueprint_version,node_id,kind,preferences,learner_context,input_blueprint,result,status,expires_at)
 select pg_temp.tid(n),owner_id,id,version,pg_temp.tid(12),'discover','{}','{}',public.read_blueprint_snapshot_v2(owner_id),
 '{"status":"discovered","candidates":[{"video":{"videoId":"abcdefghijk","title":"Saved video"},"transcript":{"status":"ready","language":"en","segments":[{"text":"Old source","offset":0,"duration":1000},{"text":"Again","offset":1000,"duration":1000}]}}]}',
 'ready',clock_timestamp()+interval '120 seconds' from public.blueprints where owner_id=pg_temp.tid(1)
$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.tid(1),'role','authenticated')::text,true);
select pg_temp.source(60);
set local role authenticated;
select public.begin_translation_run(pg_temp.req(60)||jsonb_build_object('sourceRunId',pg_temp.tid(60)));
reset role;
set local role service_role;
select public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(60),pg_temp.tid(96),pg_temp.skill(),'deepseek-v4-flash');
select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(60),pg_temp.tid(96),pg_temp.result());
reset role;
set local role authenticated;
select public.begin_translation_run(pg_temp.req(61)||jsonb_build_object('sourceRunId',pg_temp.tid(60)));
reset role;
update public.path_nodes set archived_at=clock_timestamp() where id=pg_temp.tid(12);
set local role authenticated;
select is(public.read_translation_run(pg_temp.tid(61))->>'clear_reason','source_changed','archived active node clears requested queued run');
reset role;
select is((select status from private.translation_runs where id=pg_temp.tid(60)),'ready','reconcile does not scan and mutate unrelated completed history');
select is((select remaining from private.translation_run_quotas where owner_id=pg_temp.tid(1)),1,'source-changed unclaimed run refunds once');
set local role authenticated;
select is(public.read_translation_run(pg_temp.tid(60))->>'clear_reason','source_changed','requested old ready result is hidden and erased when archived');
reset role;
update public.path_nodes set archived_at=null where id=pg_temp.tid(12);
update private.translation_run_quotas set remaining=5 where owner_id=pg_temp.tid(1);
update private.resource_retention_policies set window_seconds=1 where owner_id=pg_temp.tid(1);
select pg_temp.source(70);
set local role authenticated;
select public.begin_translation_run(pg_temp.req(70)||jsonb_build_object('sourceRunId',pg_temp.tid(70)));
reset role;
set local role service_role;
select public.claim_translation_run(pg_temp.tid(1),pg_temp.tid(70),pg_temp.tid(97),pg_temp.skill(),'deepseek-v4-flash');
select public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(70),pg_temp.tid(97),pg_temp.result());
reset role;
set local role authenticated;
select public.begin_translation_run(pg_temp.req(71)||jsonb_build_object('sourceRunId',pg_temp.tid(70)));
reset role;
select pg_sleep(1.05);
set local role authenticated;
select public.read_resource_run(pg_temp.tid(70));
reset role;
select is((select status from private.translation_runs where id=pg_temp.tid(70)),'cleared','existing original expiry mechanism clears completed translation without translation read');
select is((select clear_reason from private.translation_runs where id=pg_temp.tid(71)),'expired','queued derivative inherits expired clearing reason');
select is((select remaining from private.translation_run_quotas where owner_id=pg_temp.tid(1)),4,'expiry refunds queued once and never completed claim');
set local role service_role;
select is(public.finish_translation_run(pg_temp.tid(1),pg_temp.tid(70),pg_temp.tid(97),'{}')->>'status','cleared','expired completion cannot revive body or require discarded text');
reset role;
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('private.translation_runs'::regclass,'private.translation_run_quotas'::regclass,'private.translation_run_leases'::regclass)),'all new private tables use RLS defense in depth');
select ok((select bool_and(not prosecdef) from pg_proc where oid in ('public.begin_translation_run(jsonb)'::regprocedure,'public.read_translation_run(uuid)'::regprocedure,'public.cancel_translation_run(uuid)'::regprocedure,'public.claim_translation_run(uuid,uuid,uuid,jsonb,text)'::regprocedure,'public.finish_translation_run(uuid,uuid,uuid,jsonb)'::regprocedure)),'all public RPC wrappers remain invoker');
select * from finish();
rollback;
